describe('Clear All Filters Button', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should clear all applied filters when clear button is clicked', () => {
    // Apply multiple filters
    cy.get('[data-testid="filter-input-category"]').type('books');
    cy.get('[data-testid="filter-input-author"]').type('J.K. Rowling');
    cy.get('[data-testid="filter-input-price"]').type('10');
    cy.get('[data-testid="apply-filters-btn"]').click();

    // Verify filters are applied
    cy.get('[data-testid="filter-results-count"]').should('contain', '3 results');
    cy.get('[data-testid="filter-category"]').should('contain', 'books');
    cy.get('[data-testid="filter-author"]').should('contain', 'J.K. Rowling');
    cy.get('[data-testid="filter-price"]').should('contain', '10');

    // Click clear button
    cy.get('[data-testid="clear-filters-btn"]').click();

    // Verify filters are cleared
    cy.get('[data-testid="filter-results-count"]').should('contain', '0 results');
    cy.get('[data-testid="filter-category"]').should('not.exist');
    cy.get('[data-testid="filter-author"]').should('not.exist');
    cy.get('[data-testid="filter-price"]').should('not.exist');

    // Verify page is still visible
    cy.get('[data-testid="search-results"]').should('be.visible');
  });

  it('should not clear filters when clear button is disabled', () => {
    // Apply filters
    cy.get('[data-testid="filter-input-category"]').type('books');
    cy.get('[data-testid="filter-input-author"]').type('J.K. Rowling');
    cy.get('[data-testid="filter-input-price"]').type('10');
    cy.get('[data-testid="apply-filters-btn"]').click();

    // Verify filters are applied
    cy.get('[data-testid="filter-results-count"]').should('contain', '3 results');

    // Disable clear button
    cy.get('[data-testid="clear-filters-btn"]').should('be.visible');
    cy.get('[data-testid="clear-filters-btn"]').click();
    cy.get('[data-testid="clear-filters-btn"]').should('be.disabled');

    // Verify clear button is disabled
    cy.get('[data-testid="clear-filters-btn"]').should('have.attr', 'disabled');

    // Verify filters are still applied
    cy.get('[data-testid="filter-results-count"]').should('contain', '3 results');

    // Verify page is still visible
    cy.get('[data-testid="search-results"]').should('be.visible');
  });
});
